// Driver — spec-compliant ERR2 cancellation
// ════════════════════════════════════════════════════════════

class ahb_driver extends uvm_driver #(ahb_txn);
  `uvm_component_utils(ahb_driver)

  virtual ahb_if vif;
  ahb_txn req_q[$];        // for data-phase pairing
  ahb_txn cancelled_txn;   // txn that was cancelled by ERR2 and must be re-issued

  function new(string name="ahb_driver", uvm_component parent=null);
    super.new(name, parent);
    cancelled_txn = null;
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    if (!uvm_config_db#(virtual ahb_if)::get(this, "", "vif", vif))
      `uvm_fatal("DRV", "Could not get vif")
  endfunction

  task run_phase(uvm_phase phase);
    vif.drv_cb.HSEL   <= 1'b0;
    vif.drv_cb.HTRANS <= 2'b00;
    vif.drv_cb.HADDR  <= 32'h0;
    vif.drv_cb.HWRITE <= 1'b0;
    vif.drv_cb.HSIZE  <= 3'b010;
    vif.drv_cb.HBURST <= 3'b000;
    vif.drv_cb.HWDATA <= 32'h0;

    wait(vif.HRESETn);
    @(vif.drv_cb);

    fork
      addr_phase_task();
      data_phase_task();
    join
  endtask

  task addr_phase_task();
  ahb_txn last_issued;
  last_issued = null;

  forever begin
    // ----- ERR1 detection: HRESP=1 AND HREADYOUT=0 -----
    // Detect the first cycle of the error response. The next cycle
    // will be ERR2, during which we must drive HTRANS=IDLE to
    // cancel the pipelined transfer.
    if (vif.drv_cb.HRESP === 1'b1 && vif.drv_cb.HREADYOUT === 1'b0) begin
      vif.drv_cb.HSEL   <= 1'b0;
      vif.drv_cb.HTRANS <= 2'b00;  // IDLE — cancels the next transfer
      vif.drv_cb.HADDR  <= 32'h0;
      vif.drv_cb.HWRITE <= 1'b0;
      vif.drv_cb.HSIZE  <= 3'b010;
      vif.drv_cb.HBURST <= 3'b000;

      // The txn that was on the bus during ERR1 (held into ERR2) is
      // the one we just cancelled. It needs to be re-issued.
      if (last_issued != null) begin
        cancelled_txn = last_issued;
        last_issued   = null;
        // Pop it from the queue so the data phase task doesn't double-count
        if (req_q.size() > 0 && req_q[$] == cancelled_txn) begin
          void'(req_q.pop_back());
        end
      end

      @(vif.drv_cb);
      continue;
    end

    // ----- Normal driving when slave is ready -----
    if (vif.drv_cb.HREADYOUT === 1'b1) begin
      // Re-issue priority: a previously cancelled txn comes before a new sequence item.
      if (cancelled_txn != null) begin
        drive_address_phase(cancelled_txn);
        last_issued   = cancelled_txn;
        cancelled_txn = null;
        req_q.push_back(last_issued);
        @(vif.drv_cb);
        continue;
      end

      req = null;
      seq_item_port.try_next_item(req);

      if (req != null) begin
        drive_address_phase(req);
        last_issued = req;
        req_q.push_back(req);
        @(vif.drv_cb);
        seq_item_port.item_done();
      end
      else begin
        vif.drv_cb.HSEL   <= 1'b0;
        vif.drv_cb.HTRANS <= 2'b00;
        last_issued       = null;
        @(vif.drv_cb);
      end
    end
    else begin
      // Wait state (HREADYOUT=0). Hold and re-evaluate next cycle.
      @(vif.drv_cb);
    end
  end
endtask

  // Drive a single address phase onto the bus.
  task drive_address_phase(ahb_txn t);
    vif.drv_cb.HSEL   <= 1'b1;
    vif.drv_cb.HTRANS <= t.trans;
    vif.drv_cb.HADDR  <= t.addr;
    vif.drv_cb.HWRITE <= t.write;
    vif.drv_cb.HSIZE  <= t.size;
    vif.drv_cb.HBURST <= t.burst;
  endtask

  task data_phase_task();
    ahb_txn d_req;
    forever begin
      wait(req_q.size() > 0);
      d_req = req_q.pop_front();

      if (d_req.write) vif.drv_cb.HWDATA <= d_req.wdata;

      do begin
        @(vif.drv_cb);
      end while (vif.drv_cb.HREADYOUT !== 1'b1);
    end
  endtask
endclass

