class ahb_monitor extends uvm_monitor;
  `uvm_component_utils(ahb_monitor)

  virtual ahb_if vif;
  uvm_analysis_port #(ahb_txn) ap;

  function new(string name="ahb_monitor", uvm_component parent=null);
    super.new(name, parent);
    ap = new("ap", this);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    if (!uvm_config_db#(virtual ahb_if)::get(this, "", "vif", vif))
      `uvm_fatal("MON", "Could not get vif")
  endfunction

  task run_phase(uvm_phase phase);
    ahb_txn pending_q[$];
    ahb_txn data_phase_txn;
    ahb_txn new_addr_txn;

    wait(vif.HRESETn);
    data_phase_txn = null;

    forever begin
      @(vif.mon_cb);

      // ---------- BUS TRACE ----------
      $display("[MON %0t] BUS: HSEL=%0b HTRANS=%0b HADDR=0x%08h HWRITE=%0b HSIZE=%0b HWDATA=0x%08h HRDATA=0x%08h HREADY=%0b HRESP=%0b | q.size=%0d in_flight=%0s",
               $time,
               vif.mon_cb.HSEL, vif.mon_cb.HTRANS, vif.mon_cb.HADDR,
               vif.mon_cb.HWRITE, vif.mon_cb.HSIZE,
               vif.mon_cb.HWDATA, vif.mon_cb.HRDATA,
               vif.mon_cb.HREADY, vif.mon_cb.HRESP,
               pending_q.size(),
               (data_phase_txn != null) ? $sformatf("addr=0x%0h", data_phase_txn.addr) : "NONE");

      // Data phase completion
      if (data_phase_txn != null && vif.mon_cb.HREADY === 1'b1) begin
        if (data_phase_txn.write)
          data_phase_txn.wdata = vif.mon_cb.HWDATA;
        else
          data_phase_txn.rdata = vif.mon_cb.HRDATA;
        data_phase_txn.resp = vif.mon_cb.HRESP;

        $display("[MON %0t] DATA-PHASE COMPLETE: addr=0x%0h size=%0b write=%0b -> resp=%0b rdata=0x%08h wdata=0x%08h",
                 $time, data_phase_txn.addr, data_phase_txn.size,
                 data_phase_txn.write, data_phase_txn.resp,
                 data_phase_txn.rdata, data_phase_txn.wdata);

        ap.write(data_phase_txn);
        data_phase_txn = null;
      end

      // Address phase capture
      if (vif.mon_cb.HREADY === 1'b1 &&
          vif.mon_cb.HSEL  === 1'b1 &&
          (vif.mon_cb.HTRANS === 2'b10 || vif.mon_cb.HTRANS === 2'b11)) begin
        new_addr_txn = ahb_txn::type_id::create("new_addr_txn");
        new_addr_txn.addr  = vif.mon_cb.HADDR;
        new_addr_txn.write = vif.mon_cb.HWRITE;
        new_addr_txn.trans = vif.mon_cb.HTRANS;
        new_addr_txn.size  = vif.mon_cb.HSIZE;
        new_addr_txn.burst = vif.mon_cb.HBURST;
        pending_q.push_back(new_addr_txn);

        $display("[MON %0t] ADDR-PHASE PUSHED: addr=0x%0h size=%0b write=%0b (q.size now %0d)",
                 $time, new_addr_txn.addr, new_addr_txn.size,
                 new_addr_txn.write, pending_q.size());
      end

      // Promote pending to in-flight
      if (data_phase_txn == null && pending_q.size() > 0) begin
        data_phase_txn = pending_q.pop_front();
        $display("[MON %0t] PROMOTED to data phase: addr=0x%0h size=%0b write=%0b",
                 $time, data_phase_txn.addr, data_phase_txn.size, data_phase_txn.write);
      end
    end
  endtask
endclass

