// Scoreboard - cleaned up (logic equivalent to original, more explicit)
// ════════════════════════════════════════════════════════════

class ahb_scoreboard extends uvm_scoreboard;
  `uvm_component_utils(ahb_scoreboard)

  uvm_analysis_imp #(ahb_txn, ahb_scoreboard) ap_imp;
  bit [31:0] mem [32];

  function new(string name="ahb_scoreboard", uvm_component parent=null);
    super.new(name, parent);
    ap_imp = new("ap_imp", this);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    foreach(mem[i]) mem[i] = 32'h0;
  endfunction

  function void write(ahb_txn t);
  bit aligned_ok;
  bit size_supported;
  bit expect_error;
  bit [4:0] word_idx;
  bit [31:0] expected_rdata;

  word_idx = t.addr[6:2];
  size_supported = (t.size <= 3'b010);

  case (t.size)
    3'b000:  aligned_ok = 1'b1;
    3'b001:  aligned_ok = (t.addr[0]   == 1'b0);
    3'b010:  aligned_ok = (t.addr[1:0] == 2'b00);
    default: aligned_ok = 1'b0;
  endcase

  expect_error = !size_supported || !aligned_ok;

  $display("[SCB %0t] RX txn: addr=0x%0h size=%0b write=%0b wdata=0x%08h rdata=0x%08h resp=%0b | expect_error=%0b",
           $time, t.addr, t.size, t.write, t.wdata, t.rdata, t.resp, expect_error);

  if (expect_error) begin
    if (t.resp !== 1'b1)
      `uvm_error("SCB", $sformatf("Expected ERROR resp for addr=0x%0h size=%0b write=%0b, got resp=%0b",
                                  t.addr, t.size, t.write, t.resp))
    return;
  end

  if (t.resp !== 1'b0) begin
    `uvm_error("SCB", $sformatf("Expected OKAY resp for addr=0x%0h size=%0b write=%0b, got resp=%0b",
                                t.addr, t.size, t.write, t.resp))
    return;
  end

  if (t.write) begin
    case (t.size)
      3'b000: case (t.addr[1:0])
        2'b00: mem[word_idx][7:0]   = t.wdata[7:0];
        2'b01: mem[word_idx][15:8]  = t.wdata[7:0];
        2'b10: mem[word_idx][23:16] = t.wdata[7:0];
        2'b11: mem[word_idx][31:24] = t.wdata[7:0];
      endcase
      3'b001: case (t.addr[1])
        1'b0: mem[word_idx][15:0]  = t.wdata[15:0];
        1'b1: mem[word_idx][31:16] = t.wdata[15:0];
      endcase
      3'b010: mem[word_idx] = t.wdata;
    endcase
    $display("[SCB %0t] MEM UPDATE: mem[%0d] = 0x%08h", $time, word_idx, mem[word_idx]);
  end
  else begin
    expected_rdata = 32'h0;
    case (t.size)
      3'b000: case (t.addr[1:0])
        2'b00: expected_rdata[7:0] = mem[word_idx][7:0];
        2'b01: expected_rdata[7:0] = mem[word_idx][15:8];
        2'b10: expected_rdata[7:0] = mem[word_idx][23:16];
        2'b11: expected_rdata[7:0] = mem[word_idx][31:24];
      endcase
      3'b001: case (t.addr[1])
        1'b0: expected_rdata[15:0] = mem[word_idx][15:0];
        1'b1: expected_rdata[15:0] = mem[word_idx][31:16];
      endcase
      3'b010: expected_rdata = mem[word_idx];
    endcase

    if (t.rdata !== expected_rdata)
      `uvm_error("SCB", $sformatf("RDATA mismatch at addr=0x%0h size=%0b. Exp: 0x%08h, Act: 0x%08h",
                                  t.addr, t.size, expected_rdata, t.rdata))
  end
endfunction
endclass

// ════════════════════════════════════════════════════════════
// Functional Coverage (uvm_subscriber)
// ════════════════════════════════════════════════════════════

class ahb_coverage extends uvm_subscriber #(ahb_txn);
  `uvm_component_utils(ahb_coverage)
  
  ahb_txn txn;
  
  covergroup ahb_cg;
    option.per_instance = 1;
    
    cp_size: coverpoint txn.size {
      bins byte_sz = {3'b000};
      bins half_sz = {3'b001};
      bins word_sz = {3'b010};
      bins err_sz  = {3'b011, 3'b100, 3'b101, 3'b110, 3'b111};
    }
    
    cp_write: coverpoint txn.write {
      bins read  = {0};
      bins write = {1};
    }
    
    cp_trans: coverpoint txn.trans {
      bins nonseq = {2'b10};
      bins seq    = {2'b11};
    }
    
    cp_resp: coverpoint txn.resp {
      bins okay = {0};
      bins err  = {1};
    }
    
    cr_size_write: cross cp_size, cp_write;
    cr_size_resp:  cross cp_size, cp_resp;
  endgroup

  function new(string name="ahb_coverage", uvm_component parent=null);
    super.new(name, parent);
    ahb_cg = new();
  endfunction

  function void write(ahb_txn t);
    txn = t;
    ahb_cg.sample();
  endfunction
endclass

