module tb_top;
  logic HCLK;

  // Interface instantiation
  ahb_if vif(HCLK);
  
  // Connect Slave HREADYOUT back to system HREADY
  // Since there is only one subordinate, HREADYOUT drives the bus HREADY
  assign vif.HREADY = vif.HREADYOUT;

  // DUT instantiation
  ahb_mem dut (
    .HRESETn(vif.HRESETn),
    .HCLK(vif.HCLK),
    .HSEL(vif.HSEL),
    .HADDR(vif.HADDR),
    .HWRITE(vif.HWRITE),
    .HTRANS(vif.HTRANS),
    .HSIZE(vif.HSIZE),
    .HBURST(vif.HBURST),
    .HREADY(vif.HREADY),
    .HWDATA(vif.HWDATA),
    .HRDATA(vif.HRDATA),
    .HREADYOUT(vif.HREADYOUT),
    .HRESP(vif.HRESP)
  );

  // Clock generation
  initial begin
    HCLK = 0;
    forever #5 HCLK = ~HCLK;
  end

  // Reset generation
initial begin
  vif.HRESETn = 0;
  vif.HSEL    = 0;
  vif.HTRANS  = 0;
  vif.HADDR   = 0;
  vif.HWRITE  = 0;
  vif.HSIZE   = 3'b010;
  vif.HBURST  = 3'b000;
  vif.HWDATA  = 0;

  repeat (5) @(posedge HCLK);
  vif.HRESETn = 1;
end

  // UVM setup and test launch
  initial begin
    uvm_config_db#(virtual ahb_if)::set(null, "*", "vif", vif);
    run_test("ahb_test");
  end
endmodule

